import type { AnyZoneId, ZoneContext, ZoneFactory, ZoneId } from './types';
import { EXAMPLE_ZONE } from './types';

/**
 * Zone registry.
 *
 * Every `src/zones/<id>/index.ts` exporting `createZone` is picked up automatically — zone
 * threads do not edit this file, and do not need to. A missing zone degrades to a message: the
 * rest of the museum still renders, and the capture harness still produces a frame.
 */
type Module = { createZone: ZoneFactory };

const modules = import.meta.glob<Module>('./*/index.ts');

export const ZONE_IDS: ZoneId[] = ['pyramid', 'exterior', 'denon', 'sully', 'richelieu'];
export const ALL_ZONE_IDS: AnyZoneId[] = [...ZONE_IDS, EXAMPLE_ZONE];

export const ZONE_LABELS: Record<AnyZoneId, string> = {
  pyramid: 'Pyramide (Cour Napoléon)',
  exterior: 'Exterior wings',
  denon: 'Denon wing',
  sully: 'Sully wing',
  richelieu: 'Richelieu wing',
  example: 'Proof gallery',
};

/**
 * Zone id -> module key. The proof gallery lives in `_example/` (leading underscore keeps it out
 * of the zone-thread naming space), so an id may map to a differently named directory.
 */
export function moduleKey(id: string): string | undefined {
  for (const candidate of [`./${id}/index.ts`, `./_${id}/index.ts`]) {
    if (candidate in modules) return candidate;
  }
  return undefined;
}

export function zoneAvailable(id: string): boolean {
  return moduleKey(id) !== undefined;
}

export function availableZones(): AnyZoneId[] {
  return ALL_ZONE_IDS.filter((id) => zoneAvailable(id));
}

export interface LoadedZone {
  id: AnyZoneId;
  zone: import('./types').Zone | null;
  error?: string;
}

/**
 * Load one zone. Never throws: a missing or broken zone returns a null zone and an honest error
 * string that the HUD and the harness report.
 */
export async function loadZone(id: AnyZoneId, ctx: ZoneContext): Promise<LoadedZone> {
  const key = moduleKey(id);
  const loader = key ? modules[key] : undefined;
  if (!loader) {
    return { id, zone: null, error: `zone "${id}" is not built yet (no src/zones/${id}/index.ts)` };
  }
  try {
    const mod = await loader();
    if (typeof mod.createZone !== 'function') {
      return { id, zone: null, error: `zone "${id}" does not export createZone` };
    }
    const zone = await mod.createZone(ctx);
    return { id, zone };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    console.error('[zones] failed to load', id, err);
    return { id, zone: null, error: `zone "${id}" failed to build: ${message}` };
  }
}
